// Las filas antiguas guardan el remitente entero ({"emailAddress":{...}}): nos quedamos con la dirección
const soloDireccion = v => {
  if (v && typeof v === 'object') return v.emailAddress?.address || v.address || '';
  const t = String(v ?? '').trim();
  if (!t.startsWith('{')) return t;
  try { const o = JSON.parse(t); return o.emailAddress?.address || o.address || t; } catch (e) { return t; }
};
const data = $input.first().json;

let fechaFormateada = data.fecha_recepcion || '';

const fechaSheets = Number(fechaFormateada);

if (!isNaN(fechaSheets) && fechaSheets > 0) {
  const fecha = new Date((fechaSheets - 25569) * 86400 * 1000);
  fechaFormateada = fecha.toLocaleDateString('es-ES', {
    day: '2-digit',
    month: '2-digit',
    year: 'numeric'
  });
} 

return [{
  json: {
    ...data,
    fecha_recepcion: fechaFormateada,
    email_origen: soloDireccion(data.email_origen)
  }
}];

const cabecera = $('Recuperamos fecha y hora').first().json;
// Leemos filas devuelve un elemento vacío cuando la liquidación no tiene líneas
const lineas = $('Leemos filas').all().map(l => l.json).filter(l => Object.keys(l).length > 0);
const pdfBase64 = $('Extract from File').first().json.pdf_base64;
// Extract from Adjuntos no se ejecuta cuando la liquidación no tiene adjuntos
const adjuntos = $('Extract from Adjuntos').isExecuted ? $('Extract from Adjuntos').all().map(i => i.json) : [];

const jsonT2000 = {
  cabecera: {
    CIFEmpresa: cabecera.cliente_cif.toString(),
    Fecha: cabecera.fecha_emision,
    CIFCliente: cabecera.emisor_cif.toString(),
    Comentario: cabecera.numero_factura.toString(),
    TotalImporte: cabecera.total_bruto,
    Dto: cabecera.dto,
    BaseImponible: cabecera.total_base,
    IVA: cabecera.total_iva_porcentaje,
    Moneda: cabecera.moneda,
    TotalIva: cabecera.total_iva_importe,
    TotalTotal: cabecera.total_factura,
    Comentario2: cabecera.notas || "",
    PctRetencion: cabecera.total_irpf_porcentaje,
    Retencion: cabecera.total_irpf_importe,
    Persona: cabecera.email_origen,
    TrLiquidaciones: cabecera.fecha_recepcion
  },
  lineas: lineas.map(linea => ({
    Linea: linea.numero_linea,
    //Articulo: linea.contrato || "",
    //Descripcion: linea.descripcion,
    //CCoste: linea.centro_coste,
    Cantidad: linea.cantidad,
    Precio: linea.precio_unitario,
    Iva: linea.iva_porcentaje,
    CuotaIva: linea.iva_importe,
    Importe: linea.importe_linea_sin_iva,
    Total: linea.importe_linea_total,
    Dto: linea.descuento_porcentaje,
    Vehiculo: linea.vehiculo || "",
    Remolque: linea.remolque || "",
    Fecha: linea.fecha || "",
    Movimiento: linea.movimiento || "",
    Pedido: linea.pedido || "",
    Referencias: String(linea.referencias ?? '').split('|').map(r => r.trim()).filter(Boolean)
  })),
  documento: pdfBase64,
  adjuntos: adjuntos
};

return [{ json: jsonT2000 }]

// Normaliza la respuesta de T2000 (o el error de la llamada) para decidir si se marca Enviada o Rechazada
return $input.all().map((item, i) => {
  const r = item.json;
  let ok = false, numero = '', motivo = '', pendiente = false, aviso = '';

  if (r.error) {
    const e = r.error;
    motivo = 'Error llamando a T2000: ' + (typeof e === 'string' ? e : ([e.message, e.description].filter(Boolean).join(' — ') || JSON.stringify(e)));
  } else {
    try {
      const body = typeof r.data === 'string' ? JSON.parse(r.data) : r;
      ok = body.success === true;
      numero = body.numero ?? '';
      motivo = body.info ?? '';
      // success con estado pendiente_confirmacion: la liquidación NO está registrada en T2000 hasta que se confirmen los movimientos
      pendiente = ok && String(body.estado ?? '').trim().toLowerCase() === 'pendiente_confirmacion';
      aviso = body.avisos ?? '';
    } catch (e) {
      motivo = 'Respuesta no válida de T2000: ' + String(r.data);
    }
  }

  if (pendiente && !String(aviso).trim()) aviso = 'Pendiente de confirmación en T2000';
  return { json: { ok, pendiente, numero, motivo: String(motivo).slice(0, 500), aviso: String(aviso).slice(0, 1000), data: r.data }, pairedItem: i };
});

// Leemos adjuntos devuelve un elemento vacío cuando no hay adjuntos: nos quedamos solo con los que tienen archivo
const conArchivo = $input.all()
  .map((item, i) => ({ json: item.json, pairedItem: i }))
  .filter(item => item.json.drive_file_id);

return conArchivo.length ? conArchivo : [{ json: { sin_adjuntos: true }, pairedItem: 0 }];

